-- ===== section: dedupe =====
-- GoWayfind photo dedupe. Idempotent. Edits only the photo arrays in wf_inventory.signals.
-- Never deletes storage objects or rows, never inserts places, never touches wf_place_photo.
-- Rule: when a live photo and a newly staged photo show the same scene, the staged one wins,
-- but the live one is only removed once the staged URL is actually in the row (after upload + apply.sql).

create or replace function pg_temp.drop_url(s jsonb, u text) returns jsonb language sql immutable as $$
  select s
   || jsonb_build_object('photos', coalesce((select jsonb_agg(e order by o) from jsonb_array_elements(coalesce(s->'photos','[]')) with ordinality t(e,o) where e #>> '{}' <> u),'[]'))
   || jsonb_build_object('photo_gallery', coalesce((select jsonb_agg(e order by o) from jsonb_array_elements(coalesce(s->'photo_gallery','[]')) with ordinality t(e,o) where coalesce(e->>'url','') <> u),'[]'))
   || jsonb_build_object('haunt_photo_gallery', coalesce((select jsonb_agg(e order by o) from jsonb_array_elements(coalesce(s->'haunt_photo_gallery','[]')) with ordinality t(e,o) where coalesce(e->>'url','') <> u),'[]'))
   || jsonb_build_object('christmas_photo_gallery', coalesce((select jsonb_agg(e order by o) from jsonb_array_elements(coalesce(s->'christmas_photo_gallery','[]')) with ordinality t(e,o) where coalesce(e->>'url','') <> u),'[]'))
$$;
-- moves URL u to position 1 of signals.photos and photo_gallery when present there
create or replace function pg_temp.cover(s jsonb, u text) returns jsonb language sql immutable as $$
  select s
   || case when coalesce(s->'photos','[]') @> to_jsonb(array[u]) then jsonb_build_object('photos', to_jsonb(array[u]) || coalesce((select jsonb_agg(e order by o) from jsonb_array_elements(s->'photos') with ordinality t(e,o) where e #>> '{}' <> u),'[]')) else '{}'::jsonb end
   || case when exists(select 1 from jsonb_array_elements(coalesce(s->'photo_gallery','[]')) e where e->>'url'=u) then jsonb_build_object('photo_gallery', (select jsonb_agg(e order by (e->>'url')<>u, o) from jsonb_array_elements(s->'photo_gallery') with ordinality t(e,o))) else '{}'::jsonb end
$$;
